    effects: 'import { useEffect, useState } from "react";\n\nfunction Profile() {\n  const [user, setUser] = useState(null);\n\n  useEffect(() => {\n    console.log("Component mounted - fetch goes here");\n    // fetch("/api/me").then(r => r.json()).then(setUser);\n  }, []);   // [] = only once\n\n  return <p>{user ? user.name : "Loading..."}</p>;\n}\n\nexport default Profile;',
    context: 'import { createContext, useContext } from "react";\n\nconst ThemeCtx = createContext("light");\n\nfunction DeepChild() {\n  const theme = useContext(ThemeCtx);     // skips 5 levels\n  return <p>Current theme: {theme}</p>;\n}\n\nfunction App() {\n  return (\n    <ThemeCtx.Provider value="dark">\n      <DeepChild />\n    </ThemeCtx.Provider>\n  );\n}\n\nexport default App;',
    custom_hooks: 'import { useEffect, useState } from "react";\n\nfunction useFetch(url) {\n  const [data, setData] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    const ctrl = new AbortController();\n    fetch(url, { signal: ctrl.signal })\n      .then(r => { if (!r.ok) throw new Error(r.status); return r.json(); })\n      .then(setData)\n      .catch(e => e.name !== "AbortError" && setError(e.message))\n      .finally(() => setLoading(false));\n    return () => ctrl.abort();\n  }, [url]);\n\n  return { data, loading, error };\n}\n\n// Usage: const { data, loading } = useFetch("/api/students");',
