    router: 'import { BrowserRouter, Routes, Route, Link } from "react-router-dom";\n\nexport default function App() {\n  return (\n    <BrowserRouter>\n      <nav>\n        <Link to="/">Home</Link> | <Link to="/about">About</Link>\n      </nav>\n      <Routes>\n        <Route path="/" element={<Home />} />\n        <Route path="/about" element={<About />} />\n        <Route path="*" element={<p>404 - Not found</p>} />\n      </Routes>\n    </BrowserRouter>\n  );\n}\n\nfunction Home() { return <h1>Home page</h1>; }\nfunction About() { return <h1>About us</h1>; }',
    data_fetching: 'import { useEffect, useState } from "react";\n\nfunction Students() {\n  const [data, setData] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() => {\n    const ctrl = new AbortController();\n    fetch("/api/students", { signal: ctrl.signal })\n      .then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })\n      .then(setData)\n      .catch(e => e.name !== "AbortError" && setError(e.message))\n      .finally(() => setLoading(false));\n    return () => ctrl.abort();\n  }, []);\n\n  if (loading) return <p>Loading...</p>;\n  if (error) return <p className="error">Error: {error}</p>;\n  if (!data?.length) return <p>No students yet</p>;\n\n  return <ul>{data.map(s => <li key={s.id}>{s.name} - {s.marks}</li>)}</ul>;\n}\n\nexport default Students;',
    performance: 'import { useState } from "react";\n\n// The fastest render is the one you never trigger:\n// colocate state in the component that actually uses it.\nfunction SearchBox() {\n  const [q, setQ] = useState("");\n  return <input value={q} onChange={e => setQ(e.target.value)} />;\n}\n\n// Measure first: React DevTools Profiler -> Record -> interact -> stop.\n// Optimize ONLY what the profiler flags.\n',
    state_libraries: 'import { create } from "zustand";\n\nconst useCart = create(set => ({\n  items: [],\n  add: item => set(s => ({ items: [...s.items, item] })),\n  clear: () => set({ items: [] })\n}));\n\n// Any component, no Provider needed:\n// const items = useCart(s => s.items);\n// const add = useCart(s => s.add);\n\nconsole.log("Stores subscribe by slice - only matching components re-render");',
